namespace KotlinCompiler;
public enum TokenType {
    EOF, IDENTIFIER, NUMBER, STRING, KEYWORD,
    LPAREN, RPAREN, LBRACE, RBRACE, COMMA, DOT, COLON, SEMICOLON, ARROW,
    ASSIGN, PLUS, MINUS, STAR, SLASH, PERCENT,
    INCREMENT, DECREMENT,
    EQ, NE, LT, GT, LE, GE, AND, OR, NOT,
    PLUS_ASSIGN, MINUS_ASSIGN, STAR_ASSIGN, SLASH_ASSIGN, PERCENT_ASSIGN,
    DOTDOT, SAFE_DOT, ELVIS, LBRACKET, RBRACKET,
    NEWLINE,
}
